    #[test]
    fn emit_activates_project_node_after_pinned_pi_build_steps() {
        const VALID: &str = "\
toolchains:
  node: \"22\"
pi:
  version: \"0.75.3\"
";
        let yaml = config::load(VALID.as_bytes()).unwrap();

        let output = emit(&yaml);
        let install = output
            .find("RUN /usr/local/bin/node-install.sh 22")
            .expect("node installer layer");
        let pi_install = output
            .find("RUN npm install --prefix=/opt/pi-npm")
            .expect("Pi install layer");
        let pi_patch = output
            .find("RUN set -e; for p in /opt/pi-patches")
            .expect("Pi patch layer");
        let activation = output
            .find("ENV PATH=\"/opt/node/bin:${PATH}\"")
            .expect("project Node PATH activation");

        assert!(install < pi_install);
        assert!(pi_install < pi_patch);
        assert!(pi_patch < activation);
    }
